const ELEMENT_PROP_KEYS = new Set(["theme","value","text","label","align","hold","moveDuration","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
